function pickSum(nums, target) {
  const a = [...nums].sort((x, y) => x - y), out = [], path = [] //@init
  function explore(start, left) {
    if (left === 0) { out.push([...path]); return } //@found
    for (let i = start; i < a.length; i++) {
      if (a[i] > left) break //@prune
      path.push(a[i]) //@choose
      explore(i + 1, left - a[i]) //@explore
      path.pop() //@unchoose
    }
  }
  explore(0, target)
  return out //@done
}

