function search<T>(items: T[]): T[][] {
  const out: T[][] = []
  const path: T[] = []
  const explore = (start: number): void => {
    if (isComplete(path)) {
      out.push([...path]) // record a copy, not the shared list
      return
    }
    for (let i = start; i < items.length; i++) {
      if (!canExtend(path, items[i])) continue // prune this branch
      path.push(items[i]) // choose
      explore(i + 1) // explore (use 0 and a used set for permutations)
      path.pop() // un-choose
    }
  }
  explore(0)
  return out
}

const isComplete = <T>(path: T[]): boolean => path.length === 2
const canExtend = <T>(path: T[], item: T): boolean => path.length >= 0 && item !== undefined

