  const out = []
  const path = []
  const explore = start => {
    if (path.length === k) {
      out.push([...path])
      return
    }
    for (let x = start; x <= n; x++) {
      if (n - x + 1 < k - path.length) break
      path.push(x)
      explore(x + 1)
    }
  }
  explore(1)
  return out
}

